'use client';
import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import type { snapshotFor, contextFor } from '@/server/workshop';
import type { EquipmentStatus, Role } from '@/domain/types';
type Snapshot = Awaited<ReturnType<typeof snapshotFor>>;
type Context = Awaited<ReturnType<typeof contextFor>>;
type Option = { value: string; label: string };
type Field = { name: string; label: string; type?: 'text' | 'number' | 'password' | 'textarea' | 'select' | 'multi' | 'hidden'; value?: string | string[]; options?: Option[]; step?: string; min?: string; required?: boolean };
type ModalSpec = { title: string; action: string; fields: Field[]; note?: string };
const staff = [{ value: 'tamara', label: 'Tamara · Administrator' }, { value: 'juan-jacobo', label: 'Juan Jacobo · Workshop manager' }, { value: 'juanita', label: 'Juanita · Warehouse clerk' }, { value: 'brian', label: 'Brian · Technician' }, { value: 'nicolas', label: 'Nicolás · Technician' }, { value: 'alan', label: 'Álan · Technician' }, { value: 'anderson', label: 'Anderson · Technician' }];
const screens = [['overview', 'Overview'], ['orders', 'Service orders'], ['directory', 'Customers & vehicles'], ['inventory', 'Warehouse'], ['purchasing', 'Purchasing'], ['equipment', 'Equipment'], ['costs', 'Costs & invoices'], ['reports', 'Reports & history'], ['simulation', 'Simulation']] as const;
type Screen = typeof screens[number][0];
const allowed: Record<Role, Screen[]> = { Administrator: screens.map(([id]) => id), 'Workshop manager': ['overview', 'orders', 'directory', 'equipment', 'costs', 'reports'], 'Warehouse clerk': ['overview', 'inventory', 'purchasing', 'equipment', 'reports'], Technician: ['orders', 'inventory'] };
const money = (cents: number | null | undefined) => cents === null || cents === undefined ? 'Restricted' : new Intl.NumberFormat('en-US', { style: 'currency', currency: 'COP', maximumFractionDigits: 2 }).format(cents / 100);
const qty = (milli: number) => new Intl.NumberFormat('en-US', { maximumFractionDigits: 3 }).format(milli / 1000);
const dateAt = (minute: number) => new Intl.DateTimeFormat('en-US', { timeZone: 'America/Bogota', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(Date.parse('2026-11-20T09:00:00-05:00') + minute * 60000));
const hidden = (name: string, value: string): Field => ({ name, label: name, type: 'hidden', value });
function Badge({ children, color = '' }: { children: ReactNode; color?: string }) { return <span className={`badge ${color}`}>{children}</span>; }
function Status({ value }: { value: string }) { return <Badge color={['Working', 'Running', 'In progress', 'Fulfilled', 'Received'].includes(value) ? 'teal' : ['Idle', 'On hold', 'Pending', 'Open', 'Acknowledged', 'Ready for review'].includes(value) ? 'amber' : value.includes('Unknown') ? 'red' : ''}>{value}</Badge>; }
function Panel({ title, subtitle, action, children }: { title: string; subtitle?: string; action?: ReactNode; children: ReactNode }) { return <section className="panel"><div className="panel-header"><div><h2>{title}</h2>{subtitle && <p className="muted">{subtitle}</p>}</div>{action}</div>{children}</section>; }
function Metric({ label, value, note }: { label: string; value: ReactNode; note: string }) { return <div className="metric"><span className="metric-label">{label}</span><span className="metric-value">{value}</span><span className="metric-note">{note}</span></div>; }
function Modal({ spec, busy, error, close, submit }: { spec: ModalSpec; busy: boolean; error: string; close: () => void; submit: (values: Record<string, unknown>) => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { ref.current?.showModal(); }, []);
  function onSubmit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const values: Record<string, unknown> = Object.fromEntries(form); for (const field of spec.fields.filter(field => field.type === 'multi')) values[field.name] = form.getAll(field.name); submit(values); }
  return <dialog ref={ref} onCancel={event => { if (busy) event.preventDefault(); else close(); }} aria-labelledby="modal-title"><form onSubmit={onSubmit}><div className="dialog-header"><h2 id="modal-title">{spec.title}</h2><button className="icon-button" aria-label="Close dialog" type="button" disabled={busy} onClick={close}>×</button></div>{spec.note && <p className="muted">{spec.note}</p>}{spec.fields.map(field => field.type === 'hidden' ? <input type="hidden" name={field.name} value={String(field.value)} key={field.name} /> : field.type === 'multi' ? <fieldset key={field.name}><legend>{field.label}</legend>{field.options?.map(option => <label className="check-field" key={option.value}><input type="checkbox" name={field.name} value={option.value} defaultChecked={Array.isArray(field.value) && field.value.includes(option.value)} />{option.label}</label>)}</fieldset> : <label className="field" key={field.name}>{field.label}{field.type === 'select' ? <select name={field.name} defaultValue={String(field.value || '')} required={field.required !== false}>{field.options?.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : field.type === 'textarea' ? <textarea name={field.name} rows={3} defaultValue={String(field.value || '')} required={field.required !== false} maxLength={500} /> : <input name={field.name} type={field.type || 'text'} defaultValue={String(field.value || '')} step={field.step || '0.001'} min={field.min} required={field.required !== false} maxLength={field.type === 'password' ? 128 : 300} autoComplete={field.type === 'password' ? 'current-password' : undefined} />}</label>)}<p role="alert" className="error">{error}</p><button type="submit" className="primary" disabled={busy}>{busy ? 'Saving…' : spec.action === 'account.switch' ? 'Sign in to this account' : 'Confirm'}</button></form></dialog>;
}

export default function Workshop() {
  const [context, setContext] = useState<Context | null>(null); const [data, setData] = useState<Snapshot | null>(null);
  const [loading, setLoading] = useState(true); const [view, setView] = useState<Screen>('overview'); const [selectedOrder, setSelectedOrder] = useState('SO-1042');
  const [modal, setModal] = useState<ModalSpec | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [connected, setConnected] = useState(true);
  const [registering, setRegistering] = useState(false); const [workspaceCode, setWorkspaceCode] = useState('workshop-demo'); const [loginUser, setLoginUser] = useState('tamara');
  const [reportKind, setReportKind] = useState('orders'); const [reportOrder, setReportOrder] = useState(''); const [reportFrom, setReportFrom] = useState('2026-11-20'); const [reportTo, setReportTo] = useState('2026-11-20');
  const scenarioId = context?.scenarios[0]?.id;
  const refresh = useCallback(async (id?: string) => {
    const response = await fetch(`/api/workshop${id ? `?scenario=${id}` : ''}`, { cache: 'no-store' }); const result = await response.json();
    if (!response.ok) { if (response.status === 401) { setContext(null); setData(null); } throw new Error(result.error); }
    setData((prior: Snapshot | null) => prior && prior.actor.id === result.actor.id && prior.scenario.id === result.scenario.id && prior.scenario.revision > result.scenario.revision ? prior : result); setConnected(true);
  }, []);
  const loadSession = useCallback(async () => {
    try { const response = await fetch('/api/session', { cache: 'no-store' }); if (!response.ok) { setContext(null); setData(null); return; } const session: Context = await response.json(); setData(null); setContext(session); setWorkspaceCode(session.workspace.code); await refresh(session.scenarios[0]?.id); }
    catch (failure) { setError(failure instanceof Error ? failure.message : 'Unable to connect.'); }
    finally { setLoading(false); }
  }, [refresh]);
  useEffect(() => { void loadSession(); }, [loadSession]);
  useEffect(() => { if (!scenarioId) return; const timer = setInterval(() => { if (!document.hidden) void refresh(scenarioId).catch(() => setConnected(false)); }, 2500); return () => clearInterval(timer); }, [scenarioId, refresh]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 7000); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => { if (context && !allowed[context.actor.role].includes(view)) setView(allowed[context.actor.role][0]); }, [context, view]);
  async function signIn(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError(''); const values = Object.fromEntries(new FormData(event.currentTarget));
    try { const response = await fetch('/api/session', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...values, action: registering ? 'register' : 'login' }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); if (result.code) setNotice(`Your private workspace code is ${result.code}. Keep it for your next sign-in.`); await loadSession(); }
    catch (failure) { setError(failure instanceof Error ? failure.message : 'Sign-in failed.'); } finally { setBusy(false); }
  }
  async function command(action: string, payload: Record<string, unknown> = {}) {
    if (!data || busy) return; setBusy(true); setError('');
    const body = JSON.stringify({ action, payload, scenarioId: data.scenario.id, key: crypto.randomUUID() });
    try {
      let response: Response; try { response = await fetch('/api/workshop', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body }); } catch { response = await fetch('/api/workshop', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body }); }
      const result = await response.json(); if (!response.ok) throw new Error(result.error); setModal(null); setNotice(result.action === 'equipment.event.quarantined' ? 'The out-of-order observation was quarantined for review.' : 'Operation saved. The workshop records and indicators are updated.'); await refresh(data.scenario.id);
    } catch (failure) { const message = failure instanceof Error ? failure.message : 'Operation failed.'; setError(message); if (!modal) setNotice(message); }
    finally { setBusy(false); }
  }
  function open(spec: ModalSpec) { setError(''); setModal(spec); }
  async function modalSubmit(values: Record<string, unknown>) {
    if (!modal || !context) return;
    if (modal.action === 'account.switch') {
      setBusy(true); setError(''); try { const response = await fetch('/api/session', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...values, code: context.workspace.code }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setModal(null); await loadSession(); } catch (failure) { setError(failure instanceof Error ? failure.message : 'Sign-in failed.'); } finally { setBusy(false); } return;
    }
    if (modal.action === 'clock.configure') { values.running = values.running === 'true'; values.speed = Number(values.speed); }
    await command(modal.action, values);
  }
  async function signOut() { setBusy(true); try { const response = await fetch('/api/session', { method: 'DELETE' }); if (!response.ok) throw new Error('Unable to sign out.'); setContext(null); setData(null); setError(''); } catch (failure) { setNotice(String(failure)); } finally { setBusy(false); } }
  if (loading) return <main className="loading"><span className="brand-mark">MW</span><h1>Opening your workshop…</h1></main>;
  if (!context) return <main className="login-page"><div className="login-story"><div className="brand"><span className="brand-mark">MW</span><strong>Mechanical Workshop</strong></div><p className="eyebrow">FROM SYSTEMS THINKING TO OPERATIONS</p><h1>Every resource.<br />Every order.<br />One connected workshop.</h1><p>Manage heavy-vehicle service, follow material consumption, and turn equipment observations into timely decisions.</p><div className="login-facts"><span>Traceable materials</span><span>Accountable work</span><span>Visible feedback</span></div></div><div className="login-form"><Badge color="teal">Persistent workshop simulation</Badge><h2>{registering ? 'Create your private demonstration' : 'Sign in to your workshop'}</h2><p className="muted">{registering ? 'Start an isolated workspace with the seven fictional employees. Use your chosen password for its staff accounts.' : 'Use your workspace code and employee credentials.'}</p><form onSubmit={signIn}>{registering ? <label className="field">Workspace name<input name="name" required minLength={2} maxLength={100} placeholder="My workshop demonstration" /></label> : <><label className="field">Workspace code<input name="code" value={workspaceCode} onChange={event => setWorkspaceCode(event.target.value)} required maxLength={40} autoComplete="organization" /></label><label className="field">Employee account<select name="username" value={loginUser} onChange={event => setLoginUser(event.target.value)}>{staff.map(employee => <option key={employee.value} value={employee.value}>{employee.label}</option>)}</select></label></>}<label className="field">Password<input type="password" name="password" minLength={registering ? 12 : undefined} maxLength={128} required autoComplete={registering ? 'new-password' : 'current-password'} /></label><p className="error" role="alert">{error}</p><button className="primary" type="submit" disabled={busy}>{busy ? 'Connecting…' : registering ? 'Create private demo' : 'Sign in'}</button></form><button className="text-button section-space" onClick={() => { setRegistering(!registering); setError(''); }}>{registering ? 'Use an existing workshop' : 'Create an isolated demo workspace'}</button><p className="small-note">All sample names, vehicles, operations, and costs are fictional. This application supports an academic Systems Theory demonstration.</p></div>{notice && <div className="notification" role="status">{notice}</div>}</main>;
  if (!data || data.actor.id !== context.actor.id) return <main className="loading"><h1>Loading workshop records…</h1>{error && <><p role="alert">{error}</p><button onClick={() => void loadSession()}>Retry connection</button></>}</main>;
  const role = data.actor.role; const is = (value: Role) => role === value; const admin = is('Administrator'); const manager = is('Workshop manager'); const clerk = is('Warehouse clerk'); const technician = is('Technician'); const financial = admin || manager;
  const state = data.state; const chosen = state.orders.find(order => order.id === selectedOrder) || state.orders[0];
  const orderOptions = state.orders.filter(order => ['Open', 'In progress'].includes(order.status)).map(order => ({ value: order.id, label: `${order.id} · ${state.vehicles.find(vehicle => vehicle.id === order.vehicleId)?.plate}` }));
  const itemOptions = state.items.map(item => ({ value: item.id, label: `${item.name} (${item.unit})` }));
  const orderSelect: Field = { name: 'orderId', label: 'Service order', type: 'select', options: orderOptions };
  const itemSelect: Field = { name: 'itemId', label: 'Material', type: 'select', options: itemOptions };
  const quantityField: Field = { name: 'quantity', label: 'Quantity', type: 'number', value: '1', min: '0.001' };
  const person = (id: string) => state.employees.find(employee => employee.id === id)?.name || id;
  const vehicleFor = (id: string) => state.vehicles.find(vehicle => vehicle.id === id)!;
  const orderButtons = (orderId: string, action: string, label: string, fields: Field[] = []) => <button disabled={busy} onClick={() => fields.length ? open({ title: label, action, fields: [hidden('orderId', orderId), ...fields] }) : void command(action, { orderId })}>{label}</button>;
  function ordersTable() { return <div className="table-wrap"><table><thead><tr><th>Service order</th><th>Technicians</th><th>Status</th><th className="number">{financial ? 'Operating cost' : 'Material cost'}</th><th></th></tr></thead><tbody>{state.orders.map(order => <tr key={order.id}><td><strong>{order.id}</strong><small>{vehicleFor(order.vehicleId)?.name} · {vehicleFor(order.vehicleId)?.plate}</small></td><td>{order.assigned.length ? order.assigned.map(id => <div className="avatar-row" key={id}><span className="avatar">{person(id).split(' ').map(part => part[0]).join('').slice(0, 2)}</span>{person(id)}</div>) : <span className="muted">Unassigned</span>}</td><td><Status value={order.status} /></td><td className="number">{money(financial ? data!.costs[order.id].total : data!.costs[order.id].materials)}</td><td>{allowed[role].includes('orders') && <button className="text-button" onClick={() => { setSelectedOrder(order.id); setView('orders'); }}>Open</button>}</td></tr>)}</tbody></table></div>; }
  function pageHeading(eyebrow: string, title: string, description: string, actions?: ReactNode) { return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="muted">{description}</p></div><div className="actions">{actions}</div></div>; }
  const costsTotal = Object.values(data.costs).reduce((sum, cost) => sum + (financial ? cost.total || 0 : cost.materials), 0);
  const compressor = data.equipmentStats['C-01'];
  let content: ReactNode;
  if (view === 'overview') content = <>{pageHeading('WORKSHOP CONTROL', 'Workshop overview', 'A connected view of work, materials, and equipment.')}<div className="kpis"><Metric label="Open service orders" value={state.orders.filter(order => !['Closed', 'Cancelled'].includes(order.status)).length} note="Live service order records" /><Metric label={financial ? 'Recorded operating cost' : 'Recorded material cost'} value={money(costsTotal)} note={financial ? 'Includes known estimated energy' : 'Net materials issued to orders'} /><Metric label="Compressor utilization" value={`${Math.round((compressor?.utilization || 0) * 100)}%`} note="Useful work / observed powered time" /><Metric label="Unresolved idle alerts" value={state.alerts.filter(alert => alert.status !== 'Resolved').length} note="Acknowledgement alone is not resolution" /></div><div className="columns"><div><Panel title="Service orders" subtitle="Responsibility, progress, and recorded cost">{ordersTable()}</Panel><Panel title={financial ? 'Operating cost composition' : 'Inventory material cost'}><div className="panel-body"><div className="cost-chart">{(financial ? [['materials', 'Materials'], ['labor', 'Recorded labor'], ['energy', 'Known estimated energy']] : [['materials', 'Net materials']]).map(([key, label]) => { const value = Object.values(data.costs).reduce((sum, cost) => sum + (cost[key as keyof typeof cost] || 0), 0); return <div key={key}><div className="cost-mark-label"><span>{label}</span><strong>{money(value)}</strong></div><div className="cost-track"><span style={{ width: `${costsTotal ? value / costsTotal * 100 : 0}%` }} /></div></div>; })}</div><p className="small-note">COP · Recorded costs are separate from invoice pricing. Unknown energy intervals remain explicit.</p></div></Panel></div><div><Panel title="Needs attention" subtitle="Signals for the next operational decision"><div className="panel-body"><ul className="list">{data.suggestions.filter(suggestion => suggestion.quantity > 0).map(suggestion => <li className="list-item" key={suggestion.itemId}><div><h3>{state.items.find(item => item.id === suggestion.itemId)?.name}</h3><p>Suggested purchase: {qty(suggestion.quantity)} · On hand: {qty(state.items.find(item => item.id === suggestion.itemId)!.stock)}</p></div><Badge color="amber">Replenish</Badge></li>)}{state.alerts.filter(alert => alert.status !== 'Resolved').map(alert => <li className="list-item" key={alert.id}><div><h3>{alert.equipmentId} · Idle equipment</h3><p>{dateAt(alert.at)} · {alert.status}</p></div><Badge color="amber">Review</Badge></li>)}<li className="list-item"><div><h3>Pending material requests</h3><p>{state.requests.filter(request => !request.cancelled && request.fulfilled < request.quantity).length} requests waiting for fulfillment</p></div><Badge>Warehouse</Badge></li></ul></div></Panel><Panel title="Equipment observations"><div className="panel-body">{state.equipment.map(equipment => { const stat = data.equipmentStats[equipment.id]; return <div key={equipment.id} className="asset-summary"><div className="asset-line"><strong>{equipment.name}</strong><Status value={equipment.segments.at(-1)!.status} /></div><div className="equipment-strip"><span style={{ width: `${stat.working / Math.max(1, state.clock.minute) * 100}%` }} /><span className="idle" style={{ width: `${stat.idle / Math.max(1, state.clock.minute) * 100}%` }} /><span className="unknown" style={{ width: `${(stat.unknown + stat.poweredUnknown) / Math.max(1, state.clock.minute) * 100}%` }} /></div><p className="small-note">Working {stat.working} min · Idle {stat.idle} min · Coverage {Math.round(stat.coverage * 100)}%</p></div>; })}</div></Panel></div></div></>;
  else if (view === 'orders') content = <>{pageHeading('WORKSHOP OPERATIONS', 'Service orders', 'Plan assignments, record interventions, and close reconciled work.', manager && <button className="primary" onClick={() => open({ title: 'Create service order', action: 'order.create', fields: [{ name: 'vehicleId', label: 'Vehicle', type: 'select', options: state.vehicles.map(vehicle => ({ value: vehicle.id, label: `${vehicle.name} · ${vehicle.plate}` })) }, { name: 'description', label: 'Requested service', type: 'textarea' }] })}>Create order</button>)}<Panel title="Order register">{ordersTable()}</Panel>{chosen && <Panel title={`${chosen.id} · ${vehicleFor(chosen.vehicleId)?.name}`} subtitle={chosen.description}><div className="panel-body"><div className="detail-meta"><div><dt>Vehicle</dt><dd>{vehicleFor(chosen.vehicleId)?.plate}</dd></div><div><dt>Status</dt><dd><Status value={chosen.status} /></dd></div><div><dt>Assigned technicians</dt><dd>{chosen.assigned.map(person).join(', ') || 'Not assigned'}</dd></div><div><dt>{financial ? 'Operating cost' : 'Material cost'}</dt><dd>{money(financial ? data.costs[chosen.id].total : data.costs[chosen.id].materials)}</dd></div></div><div className="actions wrap">{manager && !['Closed', 'Cancelled'].includes(chosen.status) && <><button onClick={() => open({ title: 'Assign technicians', action: 'order.assign', fields: [hidden('orderId', chosen.id), { name: 'employeeIds', label: 'Technicians', type: 'multi', value: chosen.assigned, options: state.employees.filter(employee => employee.role === 'Technician').map(employee => ({ value: employee.id, label: employee.name })) }] })}>Edit assignments</button>{chosen.status === 'Draft' && orderButtons(chosen.id, 'order.submit', 'Submit order')}{chosen.status === 'In progress' && <>{orderButtons(chosen.id, 'order.hold', 'Put on hold', [{ name: 'reason', label: 'Hold reason', type: 'textarea' }])}{orderButtons(chosen.id, 'order.review', 'Request review')}</>}{chosen.status === 'On hold' && orderButtons(chosen.id, 'order.resume', 'Resume order')}{chosen.status === 'Ready for review' && <>{orderButtons(chosen.id, 'order.close', 'Close order')}{orderButtons(chosen.id, 'order.rework', 'Return for work', [{ name: 'reason', label: 'Additional work reason', type: 'textarea' }])}</>}{['Draft', 'Open'].includes(chosen.status) && orderButtons(chosen.id, 'order.cancel', 'Cancel unused order')}</>}{technician && chosen.assigned.includes(data.actor.username) && ['Open', 'In progress'].includes(chosen.status) && <button className="primary" disabled={busy} onClick={() => void command('intervention.start', { orderId: chosen.id })}>Start new intervention</button>}</div><h3 className="section-space">Interventions</h3><ul className="list">{state.interventions.filter(intervention => intervention.orderId === chosen.id).map(intervention => <li key={intervention.id} className="list-item"><div><h3>{person(intervention.employeeId)} · {intervention.id}</h3><p>{intervention.segments.reduce((sum, segment) => sum + (segment.end ?? state.clock.minute) - segment.start, 0)} active minutes · {intervention.outcome || 'Work in progress'}</p><Status value={intervention.status} /></div>{technician && intervention.employeeId === data.actor.username && intervention.status !== 'Completed' && <div className="actions wrap"><button disabled={busy} onClick={() => void command(intervention.status === 'Running' ? 'intervention.pause' : 'intervention.resume', { interventionId: intervention.id })}>{intervention.status === 'Running' ? 'Pause' : 'Resume'}</button><button onClick={() => open({ title: 'Finish intervention', action: 'intervention.finish', fields: [hidden('interventionId', intervention.id), { name: 'outcome', label: 'Work outcome', type: 'textarea' }] })}>Finish</button></div>}</li>)}</ul><p className="small-note">Assignment does not start the timer. Paused time does not add labor cost. Review requires completed work, settled requests, and stopped equipment.</p></div></Panel>}</>;
  else if (view === 'directory') content = <>{pageHeading('CUSTOMER RECORDS', 'Customers & vehicles', 'Keep customer ownership and vehicle references connected.', manager && <><button onClick={() => open({ title: 'Register customer', action: 'customer.create', fields: [{ name: 'name', label: 'Customer name' }, { name: 'contact', label: 'Contact or department', required: false }] })}>Register customer</button><button className="primary" onClick={() => open({ title: 'Register vehicle', action: 'vehicle.create', fields: [{ name: 'customerId', label: 'Customer', type: 'select', options: state.customers.map(customer => ({ value: customer.id, label: customer.name })) }, { name: 'name', label: 'Vehicle model' }, { name: 'plate', label: 'Plate or fleet reference' }, { name: 'kind', label: 'Vehicle type', type: 'select', options: ['Truck', 'Bus', 'Heavy machinery'].map(value => ({ value, label: value })) }] })}>Register vehicle</button></>)}<Panel title="Vehicle register"><div className="table-wrap"><table><thead><tr><th>Vehicle</th><th>Type</th><th>Customer</th><th>Contact</th></tr></thead><tbody>{state.vehicles.map(vehicle => { const customer = state.customers.find(entry => entry.id === vehicle.customerId)!; return <tr key={vehicle.id}><td><strong>{vehicle.name}</strong><small>{vehicle.plate} · {vehicle.id}</small></td><td>{vehicle.kind}</td><td>{customer.name}</td><td>{customer.contact}</td></tr>; })}</tbody></table></div></Panel><Panel title="Customers"><div className="panel-body"><ul className="list">{state.customers.map(customer => <li className="list-item" key={customer.id}><div><h3>{customer.name}</h3><p>{customer.contact} · {customer.id}</p></div><Badge>{state.vehicles.filter(vehicle => vehicle.customerId === customer.id).length} vehicles</Badge></li>)}</ul></div></Panel></>;
  else if (view === 'inventory') content = <>{pageHeading('MATERIAL CONTROL', 'Warehouse', 'Every issue belongs to an order and an assigned technician.', <>{technician && <button className="primary" onClick={() => open({ title: 'Request materials', action: 'request.create', fields: [orderSelect, itemSelect, quantityField], note: 'Submitting a request does not reserve or deduct stock.' })}>Request materials</button>}{clerk && <><button onClick={() => open({ title: 'Receive stock', action: 'stock.receive', fields: [itemSelect, quantityField, { name: 'unitCost', label: 'Unit purchase cost (COP)', type: 'number', min: '.01', step: '.01' }, { name: 'reference', label: 'Unique delivery reference' }] })}>Record receipt</button><button onClick={() => open({ title: 'Adjust stock', action: 'stock.adjust', fields: [itemSelect, { ...quantityField, label: 'Signed adjustment quantity', min: undefined }, { name: 'reference', label: 'Adjustment reason', type: 'textarea' }] })}>Justified adjustment</button></>}{admin && <button onClick={() => open({ title: 'Add material', action: 'item.create', fields: [{ name: 'name', label: 'Material name' }, { name: 'sku', label: 'SKU' }, { name: 'unit', label: 'Unit (unit, set, L…)' }, { name: 'unitCost', label: 'Initial unit cost (COP)', type: 'number', step: '.01' }, { name: 'dailyDemand', label: 'Baseline daily demand', type: 'number', value: '1' }, { name: 'leadDays', label: 'Supplier lead time (days)', type: 'number', step: '1', value: '3' }, { name: 'safety', label: 'Safety stock', type: 'number', value: '2' }, { name: 'pack', label: 'Purchase pack size', type: 'number', value: '1' }] })}>Add material</button>}</>)}<Panel title="Material requests" subtitle="Partial delivery is supported; warehouse availability is revalidated on the server."><div className="table-wrap"><table><thead><tr><th>Request</th><th>Material</th><th>Requested / issued</th><th>Status</th><th></th></tr></thead><tbody>{state.requests.map(request => <tr key={request.id}><td><strong>{request.id}</strong><small>{person(request.employeeId)} · {request.orderId}</small></td><td>{state.items.find(item => item.id === request.itemId)?.name}</td><td>{qty(request.quantity)} / {qty(request.fulfilled)}</td><td><Status value={request.cancelled ? 'Cancelled' : request.fulfilled >= request.quantity ? 'Fulfilled' : request.fulfilled ? 'Partially fulfilled' : 'Pending'} /></td><td><div className="actions wrap">{!request.cancelled && request.fulfilled < request.quantity && <>{clerk && <button className="primary" onClick={() => open({ title: `Issue ${request.id}`, action: 'material.issue', fields: [hidden('requestId', request.id), { ...quantityField, value: String((request.quantity - request.fulfilled) / 1000) }] })}>Issue</button>}{(clerk || technician) && <button disabled={busy} onClick={() => void command('request.cancel', { requestId: request.id })}>Cancel remainder</button>}</>}</div></td></tr>)}</tbody></table></div></Panel><Panel title="Inventory"><div className="table-wrap"><table><thead><tr><th>Material</th><th className="number">On hand</th><th className="number">Unit cost</th><th className="number">Reorder point</th><th></th></tr></thead><tbody>{state.items.map(item => <tr key={item.id}><td><strong>{item.name}</strong><small>{item.sku} · {item.unit}</small></td><td className="number">{qty(item.stock)} {item.unit}</td><td className="number">{money(item.unitCostCents)}</td><td className="number">{technician ? '—' : qty(data.suggestions.find(suggestion => suggestion.itemId === item.id)?.point || 0)}</td><td>{admin && <button className="text-button" onClick={() => open({ title: `Reorder policy · ${item.name}`, action: 'item.settings', fields: [hidden('itemId', item.id), { name: 'dailyDemand', label: 'Baseline daily demand', type: 'number', value: String(item.dailyDemand / 1000) }, { name: 'leadDays', label: 'Lead time (days)', type: 'number', step: '1', value: String(item.leadDays) }, { name: 'safety', label: 'Safety stock', type: 'number', value: String(item.safety / 1000) }, { name: 'pack', label: 'Purchase pack size', type: 'number', value: String(item.pack / 1000) }] })}>Configure</button>}</td></tr>)}</tbody></table></div></Panel><Panel title="Stock movement ledger" subtitle="Original issue costs are preserved. Returns append a compensating movement."><div className="table-wrap"><table><thead><tr><th>Movement</th><th>Material</th><th>Quantity</th><th>Reference</th><th>Value</th><th></th></tr></thead><tbody>{[...state.movements].reverse().map(movement => <tr key={movement.id}><td><strong>{movement.kind}</strong><small>{movement.id} · {dateAt(movement.at)}</small></td><td>{state.items.find(item => item.id === movement.itemId)?.name}</td><td>{qty(movement.quantity)}</td><td>{movement.orderId || movement.reference}<small>{movement.actor}</small></td><td>{money(movement.amountCents)}</td><td>{clerk && movement.kind === 'Issue' && !['Closed', 'Cancelled'].includes(state.orders.find(order => order.id === movement.orderId)?.status || '') && <button className="text-button" onClick={() => open({ title: 'Accept material return', action: 'material.return', fields: [hidden('sourceId', movement.id), quantityField, { name: 'reason', label: 'Return reason', type: 'textarea' }] })}>Return</button>}</td></tr>)}</tbody></table></div></Panel></>;
  else if (view === 'purchasing') content = <>{pageHeading('REPLENISHMENT', 'Purchasing', 'Suggestions become stock only after approval, ordering, and receipt.')}<Panel title="Reorder suggestions" subtitle="Inventory position includes outstanding approved and ordered quantities."><div className="table-wrap"><table><thead><tr><th>Material</th><th>On hand / incoming</th><th>Reorder / target</th><th>Suggested quantity</th><th></th></tr></thead><tbody>{data.suggestions.map(suggestion => { const item = state.items.find(entry => entry.id === suggestion.itemId)!; return <tr key={item.id}><td><strong>{item.name}</strong><small>{qty(item.dailyDemand)} / day · {item.leadDays}-day lead time</small></td><td>{qty(item.stock)} / {qty(suggestion.outstanding)}</td><td>{qty(suggestion.point)} / {qty(suggestion.target)}</td><td>{suggestion.quantity ? <Badge color="amber">{qty(suggestion.quantity)} {item.unit}</Badge> : <Badge color="teal">Covered</Badge>}</td><td>{admin && suggestion.quantity > 0 && <button className="primary" onClick={() => open({ title: 'Approve replenishment', action: 'purchase.approve', fields: [hidden('itemId', item.id), { name: 'supplier', label: 'Supplier', value: 'Central Heavy Parts' }, { name: 'unitCost', label: 'Purchase unit cost (COP)', type: 'number', step: '.01', value: String(item.unitCostCents / 100) }], note: `The server will re-evaluate the current shortfall. Current suggestion: ${qty(suggestion.quantity)} ${item.unit}.` })}>Review purchase</button>}</td></tr>; })}</tbody></table></div></Panel><Panel title="Purchase orders"><div className="table-wrap"><table><thead><tr><th>Purchase</th><th>Material</th><th>Ordered / received</th><th>Status</th><th></th></tr></thead><tbody>{state.purchases.length ? state.purchases.map(purchase => <tr key={purchase.id}><td><strong>{purchase.id}</strong><small>{purchase.supplier}</small></td><td>{state.items.find(item => item.id === purchase.itemId)?.name}<small>{money(purchase.unitCostCents)} / unit</small></td><td>{qty(purchase.quantity)} / {qty(purchase.received)}</td><td><Status value={purchase.status} /></td><td><div className="actions wrap">{admin && purchase.status === 'Approved' && <button disabled={busy} onClick={() => void command('purchase.order', { purchaseId: purchase.id })}>Record order</button>}{admin && ['Approved', 'Ordered'].includes(purchase.status) && !purchase.received && <button disabled={busy} onClick={() => void command('purchase.cancel', { purchaseId: purchase.id })}>Cancel purchase</button>}{clerk && ['Ordered', 'Partially received'].includes(purchase.status) && <button className="primary" onClick={() => open({ title: `Receive ${purchase.id}`, action: 'purchase.receive', fields: [hidden('purchaseId', purchase.id), { ...quantityField, value: String((purchase.quantity - purchase.received) / 1000) }, { name: 'reference', label: 'Unique delivery reference' }] })}>Receive delivery</button>}</div></td></tr>) : <tr><td colSpan={5} className="empty">No purchase has been approved yet.</td></tr>}</tbody></table></div></Panel></>;
  else if (view === 'equipment') content = <>{pageHeading('EQUIPMENT CONTROL', 'Equipment', 'Power and useful activity are separate observations. Readings in this workspace are simulated.')}<div className="equipment-grid">{state.equipment.map(equipment => { const current = equipment.segments.at(-1)!; const stats = data.equipmentStats[equipment.id]; function event(status: EquipmentStatus) { return command('equipment.event', { equipmentId: equipment.id, status, eventId: crypto.randomUUID() }); } return <section className="equipment-card" key={equipment.id}><h2>{equipment.name}</h2><span className="asset-code">{equipment.id} · {current.orderId || 'Unallocated workshop overhead'}</span><Status value={current.status} /><div className="asset-value">{state.clock.minute - current.start} <span className="muted">min</span></div><p className="muted">In current observation state</p><dl><div><dt>Effective time</dt><dd>{stats.working} min</dd></div><div><dt>Observed idle</dt><dd>{stats.idle} min</dd></div><div><dt>Unknown intervals</dt><dd>{stats.unknown + stats.poweredUnknown} min</dd></div><div><dt>Coverage</dt><dd>{Math.round(stats.coverage * 100)}%</dd></div><div><dt>Known energy estimate</dt><dd>{money(stats.energy)}</dd></div></dl>{manager && <div className="actions wrap"><button className="primary" disabled={busy} onClick={() => void event('Working')}>Useful work</button><button disabled={busy} onClick={() => void event('Idle')}>Record idle</button><button disabled={busy} onClick={() => void event('Off')}>Power off</button><button disabled={busy} onClick={() => void event('Unknown power')}>Lose telemetry</button><button onClick={() => open({ title: `Assign equipment · ${equipment.id}`, action: 'equipment.event', fields: [hidden('equipmentId', equipment.id), hidden('eventId', crypto.randomUUID()), { ...orderSelect, options: [{ value: '', label: 'Unallocated workshop overhead' }, ...orderOptions], required: false }, { name: 'status', label: 'Observed state', type: 'select', options: ['Working', 'Idle', 'Powered unknown activity', 'Unknown power'].map(value => ({ value, label: value })) }] })}>Attach to order</button></div>}{admin && <button className="text-button" onClick={() => open({ title: `Power profile · ${equipment.id}`, action: 'equipment.settings', fields: [hidden('equipmentId', equipment.id), { name: 'workWatts', label: 'Working power (W)', type: 'number', step: '1', value: String(equipment.workWatts) }, { name: 'idleWatts', label: 'Idle power (W)', type: 'number', step: '1', value: String(equipment.idleWatts) }, { name: 'tariff', label: 'Tariff (COP/kWh)', type: 'number', step: '.01', value: String(equipment.tariffCents / 100) }], note: 'New profiles apply to new observation intervals; historical intervals keep their original values.' })}>Configure profile</button>}</section>; })}</div><div className="section-space"><Panel title="Idle alerts" subtitle="An alert opens after 15 continuous simulated minutes of observed idle."><div className="panel-body">{state.alerts.length ? [...state.alerts].reverse().map(alert => <div className="list-item" key={alert.id}><div><h3>{alert.id} · {alert.equipmentId}</h3><p>{dateAt(alert.at)} · {alert.acknowledgedBy ? `Acknowledged by ${alert.acknowledgedBy}` : 'Awaiting acknowledgement'}{alert.unverified ? ' · Current observation unverified' : ''}</p><Status value={alert.status} /></div>{manager && alert.status === 'Open' && <button disabled={busy} onClick={() => void command('alert.acknowledge', { alertId: alert.id })}>Acknowledge</button>}</div>) : <p className="muted">No idle alerts yet. Advance the clock to observe the threshold.</p>}<p className="small-note">Acknowledgement records responsibility. A confirmed return to work or power-off resolves an episode. Unknown data is never counted as measured idle or zero energy.</p></div></Panel><Panel title="Event ingestion history"><div className="panel-body">{[...state.events].reverse().slice(0, 15).map(event => <div className="list-item" key={event.id}><div><h3>{event.equipmentId} · {event.status}</h3><p>{event.id} · {dateAt(event.at)}</p></div><Badge color={event.result === 'Quarantined' ? 'amber' : 'teal'}>{event.result}</Badge></div>)}{!state.events.length && <p className="muted">Synthetic opening intervals are loaded. New observations appear here.</p>}</div></Panel></div></>;
  else if (view === 'costs') content = <>{pageHeading('SERVICE FINANCE', 'Costs & invoices', 'Operating costs use recorded quantities, time segments, and price snapshots.')}<label className="field filter-field">Service order<select value={chosen?.id || ''} onChange={event => setSelectedOrder(event.target.value)}>{state.orders.map(order => <option key={order.id} value={order.id}>{order.id} · {vehicleFor(order.vehicleId)?.name}</option>)}</select></label>{chosen && <div className="columns"><Panel title="Cost breakdown" subtitle={chosen.status === 'Closed' ? 'Reconciled closure snapshot' : 'Provisional operating cost'}><div className="panel-body">{[['Materials, net of returns', data.costs[chosen.id].materials], ['Recorded active labor', data.costs[chosen.id].labor], ['Known allocated energy estimate', data.costs[chosen.id].energy]].map(([label, value]) => <div className="cost-row" key={String(label)}><span>{label}</span><span>{money(value as number)}</span></div>)}<div className="invoice-total"><span>Operating cost</span><span>{money(data.costs[chosen.id].total)}</span></div><p className="small-note">Unknown energy intervals: {data.costs[chosen.id].unknownMinutes} min. Energy remains an estimate, even when observation coverage is complete.</p>{admin && !state.invoices.some(invoice => invoice.orderId === chosen.id) && <button className="primary section-space" disabled={busy || chosen.status !== 'Closed'} onClick={() => void command('invoice.create', { orderId: chosen.id })}>Issue educational invoice</button>}</div></Panel><Panel title="Educational invoice"><div className="panel-body">{state.invoices.filter(invoice => invoice.orderId === chosen.id).map(invoice => <article className="invoice-sheet" key={invoice.id}><h2>{invoice.id}</h2><p>{invoice.customer}<br />{invoice.vehicle}</p><p>{invoice.description}</p><p className="small-note">Issued {dateAt(invoice.at)} · {invoice.issuedBy}</p>{[['Net materials', invoice.cost.materials], ['Recorded labor', invoice.cost.labor], ['Estimated energy', invoice.cost.energy]].map(([label, value]) => <div className="cost-row" key={String(label)}><span>{label}</span><span>{money(Number(value))}</span></div>)}<div className="invoice-total"><span>Total</span><span>{money(invoice.cost.total)}</span></div><p className="small-note">Educational invoice · Cost-based demonstration pricing · No modeled tax or markup. Not an official tax document.</p><button className="section-space" onClick={() => window.print()}>Print invoice</button></article>)}{!state.invoices.some(invoice => invoice.orderId === chosen.id) && <p className="muted">Close and reconcile the order before issuing its stable invoice snapshot.</p>}</div></Panel></div>}</>;
  else if (view === 'reports') content = <>{pageHeading('OPERATIONAL EVIDENCE', 'Reports & history', 'Export actual recorded movements and time intervals for the selected period.')}<div className="form-row report-controls"><label className="field">Report type<select value={reportKind} onChange={event => setReportKind(event.target.value)}><option value="orders">Order costs</option><option value="materials">Material movements</option><option value="equipment">Equipment utilization</option>{financial && <><option value="vehicles">Costs by vehicle</option><option value="technicians">Costs by technician</option></>}</select></label><label className="field">Service order<select value={reportOrder} onChange={event => setReportOrder(event.target.value)}><option value="">All orders</option>{state.orders.map(order => <option key={order.id} value={order.id}>{order.id}</option>)}</select></label><label className="field">From date<input type="date" value={reportFrom} onChange={event => setReportFrom(event.target.value)} /></label><label className="field">Through date<input type="date" value={reportTo} onChange={event => setReportTo(event.target.value)} /></label><a className="button-link primary" href={`/api/reports?scenario=${data.scenario.id}&kind=${reportKind}&order=${encodeURIComponent(reportOrder)}&from=${reportFrom}&to=${reportTo}`}>Export period CSV</a></div><Panel title="Current order totals" subtitle="Cumulative totals below; the CSV applies the chosen date window to source records.">{ordersTable()}</Panel>{admin && <Panel title="Operation history" subtitle="Append-only records retain the initiating account, scenario time, and wall-clock timestamp."><div className="panel-body">{data.audit.map((record, index) => <div className="audit-item" key={index}><time>{dateAt(record.scenario_minute)}</time><div><strong>{record.action}</strong><small>{record.actor_name} · Recorded {new Date(record.recorded_at).toLocaleString('en-US', { timeZone: 'America/Bogota' })}</small><details><summary>Operation details</summary><pre>{JSON.stringify(record.details, null, 2)}</pre></details></div></div>)}</div></Panel>}</>;
  else content = <>{pageHeading('SYSTEMS THEORY IN ACTION', 'Simulation', 'Observe feedback, invariant enforcement, and a reproducible policy comparison.')}<Panel title="Guided operational scenario" subtitle="Uses the same server-side domain operations as manual work."><div className="panel-body"><ol className="scenario-steps"><li>Issue the baseline pending oil filters.</li><li>Advance five simulated minutes to the idle threshold.</li><li>Acknowledge the alert and confirm compressor power-off.</li><li>Finish recorded interventions.</li><li>Review and close the service order.</li><li>Issue its educational invoice.</li></ol><button className="primary" disabled={busy} onClick={() => void command('simulation.run')}>Run guided scenario</button><button className="section-space" onClick={() => open({ title: 'Reset this workspace scenario', action: 'scenario.reset', fields: [], note: 'This replaces the current operational scenario with its synthetic baseline. Audit history is retained. Other workspaces are unaffected.' })}>Reset to baseline</button><p className="small-note">The audit explicitly identifies synthetic engine activity initiated by your administrator account. It does not pretend that employees signed in and performed these actions themselves.</p></div></Panel>{data.comparison && <Panel title="Controlled versus uncontrolled policy" subtitle={`Seed ${data.comparison.seed} · ${data.comparison.jobs} identical synthetic jobs`}><div className="panel-body"><div className="table-wrap"><table><thead><tr><th>Measure</th><th>Uncontrolled policy</th><th>Controlled policy</th></tr></thead><tbody><tr><td>Material cost</td><td>{money(data.comparison.uncontrolled.materials)}</td><td>{money(data.comparison.controlled.materials)}</td></tr><tr><td>Estimated energy cost</td><td>{money(data.comparison.uncontrolled.energy)}</td><td>{money(data.comparison.controlled.energy)}</td></tr><tr><td>Powered idle time</td><td>{data.comparison.uncontrolled.idleMinutes} min</td><td>{data.comparison.controlled.idleMinutes} min</td></tr><tr><td>Unassigned requests rejected</td><td>0</td><td>{data.comparison.controlled.rejectedUnassigned}</td></tr></tbody></table></div><h3 className="section-space">Assumptions and interpretation</h3><ul className="assumptions">{data.comparison.assumptions.map(assumption => <li key={assumption}>{assumption}</li>)}</ul></div></Panel>}<Panel title="Trace the system"><div className="panel-body"><p>Input: an assigned technician’s material request. Process: validation and one atomic stock operation. Output: a delivery record and attributed cost. Feedback: a reorder suggestion followed by approval and actual receipt.</p><p>For equipment, an observation becomes information about idle time. An alert prompts a human action; acknowledgement alone does not change the physical process.</p><a href="/design/models/index.html" target="_blank" rel="noreferrer">Explore the system model atlas</a></div></Panel></>;
  return <><a className="skip-link" href="#main">Skip to content</a><div className="prototype-bar"><span><strong>Simulation workspace</strong> · {context.workspace.code}</span><div className="scenario-controls"><span>{dateAt(state.clock.minute)} · {state.clock.running ? `${state.clock.speed}× running` : 'Paused'}</span>{admin && <><button disabled={busy || state.clock.running} onClick={() => void command('clock.advance', { minutes: 5 })}>Advance 5 min</button><button disabled={busy} onClick={() => void command('clock.configure', { running: !state.clock.running, speed: state.clock.speed })}>{state.clock.running ? 'Pause clock' : 'Run clock'}</button><select aria-label="Clock speed" value={state.clock.speed} disabled={busy} onChange={event => void command('clock.configure', { running: state.clock.running, speed: Number(event.target.value) })}>{[1, 5, 30, 60].map(speed => <option key={speed} value={speed}>{speed}× speed</option>)}</select></>}</div></div><div className="app-layout"><aside className="sidebar"><a href="#overview" className="brand" onClick={event => { event.preventDefault(); setView(allowed[role][0]); }}><span className="brand-mark">MW</span><span>Mechanical<br /><strong>Workshop</strong></span></a><p className="nav-label">OPERATIONS</p><nav aria-label="Main navigation">{screens.filter(([id]) => allowed[role].includes(id)).map(([id, label], index) => <button key={id} className={`nav-item ${view === id ? 'active' : ''}`} aria-current={view === id ? 'page' : undefined} onClick={() => setView(id)}><span className="nav-glyph" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>{label}</button>)}</nav><div className="sidebar-footer"><span className="environment-mark">S</span><div><strong>{context.workspace.name}</strong><small>Persistent synthetic operations</small></div></div></aside><div className="workspace"><header className="topbar"><div className="breadcrumb">Workspace <span>/</span><strong>{screens.find(([id]) => id === view)?.[1]}</strong></div><div className="account"><span><strong>{data.actor.name}</strong><small>{role}</small></span><button onClick={() => open({ title: 'Switch employee account', action: 'account.switch', note: 'Sign in with the password for the selected account in this workspace.', fields: [{ name: 'username', label: 'Employee account', type: 'select', options: staff, value: data.actor.username }, { name: 'password', label: 'Password', type: 'password' }] })}>Switch account</button><button className="text-button" disabled={busy} onClick={() => void signOut()}>Sign out</button></div></header>{!connected && <div className="notice">Connection interrupted. Displayed values may be stale; your operation history remains on the server.</div>}<main id="main" tabIndex={-1}>{content}</main><footer className="page-footer"><span>Mechanical Workshop · {context.workspace.name}</span><span>{connected ? 'Connected' : 'Reconnecting'} · Revision {data.scenario.revision} · COP · Synthetic data</span></footer></div></div>{notice && <div className="notification" role="status">{notice}</div>}{modal && <Modal spec={modal} busy={busy} error={error} close={() => { if (!busy) setModal(null); }} submit={values => void modalSubmit(values)} />}</>;
}
